use crate::domains::kernel_opt::KernelRule;

pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // ── H: MoE dispatch (#502 + #518) — the member-rows width ladder:
        // every rung bit-identical by summation order, a measured null
        // point at 2 rows, a 5-40% losing set past the ceiling, and the
        // promoted default = the measured winner (3).
        KernelRule {
            rule_id: "expert-member-rows-width-ladder-bit-identical".to_string(),
            gpu_concept: "MECHANISM (MoE routed-expert dispatch; category H): an expert's member rows a pass is a MEASURABLE WIDTH LADDER, not a constant. The incumbent took 'an expert's member rows two at a time with all 16 activations of a chunk live' — a hard-wired constant-two shape whose live-activation set (MB x 16 floats) caps the width and leaves wider rungs unavailable. The repair reorders the loop and RAISES the width: 'tf_experts_w takes the four weight words of a 16-group as its outer loop, so four activations a member are live and three members a pass at four simdgroups fit' — each weight word unpacked once now serves all MB member rows, the live set drops to four activations a member, and the width climbs to three at four simdgroups. THE BIT-IDENTITY ORDER ARGUMENT (the law that makes every rung legal): 'Each lane sums in tf_qdot16's order and ends in the same simd_sum, so every width gives the one-row kernel's bits' — the packed pass visits each member's weight words in the one-row kernel's i-ascending order, adds nibbles ascending, and reduces with the same simd_sum; the kernel's own comments pin both halves ('the masked words read once, each input's sums in tf_qdot16's order'; 'the same chunk order and the same simd_sum per (row, output)'), and the family law behind them: 'Each kernel reads a weight once per window and keeps every row's own sums, so a row's bits are the same at any width.' The exactness contract is therefore spelled POSITIVELY: 'a change that keeps each lane's summation order is allowed' — a rung that REASSOCIATED the reduce would need a tolerance gate instead; this one does not, and bit equality stays the gate. THE MEASURED LADDER (tf-nemotron-experts, M5 Ultra; the 23 layers' up and down projections) 'went from 2.35 to 2.27 ms at 4 rows, 6.68 to 6.48 at 16, 11.93 to 11.24 at 32 and 22.57 to 20.58 at 64 (equal at 2)' — the commit's own form: 'going from 11.93 to 11.24 ms at 32 rows and 22.57 to 20.58 at 64, equal at 2' — and the gain GROWS with window width, because wider rounds give each popular expert more members to pack. THE NULL POINT: at 2 rows the measurement is flat — 'equal at 2' — and the source states the number without a mechanism; the structural reading (LABELED INFERENCE) is that an expert holding fewer members than MB never fills a wide pass, so the rung cannot engage (the pass_plan economics in the fixture encode it). THE REGIME PHYSICS (why packing pays here): 'Past 16 lanes the routed-expert kernel falls below the memory line: it streams unique expert weights at about 1 TB/s up to 8 rows, 730 GB/s at 32 and 540 GB/s at 64'; the ladder amortizes exactly that stream — the winner 'took 6% off at 32 rows and 10% at 64, bit for bit' — and the honest residue is named: 'The rest of the gap is per-member work that the weight stream does not hide.' THE MOTIVATING COST MODEL (the row-cost-model-rebroadcast rider, folded here, never a second rule): 'In the GLM-5.3 port each extra row in a window cost about 4.4 ms of GPU time, against about 2.3 ms for the row's own experts. Row kernels read every replicated weight again for every row.' — the near-2x spread between marginal-row cost and own-expert cost IS the amortization headroom a member-rows ladder harvests. THE THREE NEGATIVES (built, run, kept every bit, gained nothing — in-rule so nobody re-tries): 'an expert's member blocks spread over grid z instead of looped (the GPU already overlaps a popular expert's loop with the other 230 threadgroups a layer)'; 'the activations' floats and bf16-rounded group sums prepared once a forward instead of remade a member (50 fewer ALU ops a chunk, the same time, so the loop is not ALU-bound)'; '8-byte vector loads of the weight words and activations (slower than the compiler's own schedule)'. THE ANTI-LADDER (the width ceiling at the OTHER end): 'Six or eight members a pass, or four at two simdgroups, lose 5-40%: only two to four at four simdgroups win' — too narrow wastes the amortization, too wide (or wide at too few simdgroups) loses to the register budget; the ladder is bounded at BOTH ends and the measured loser set ships in the fixture. THE DISPATCH (the shipped shape): a config knob whose default is the measured winner — 'members: usize = 3, // routed experts' member rows a pass (bit-identical; 3: tf_experts_w; one at a time for one row)' — promoted from 2 by the measured commit; the ladder routes mb == 3 to the words-outer kernel at four simdgroups, mb >= 4 to rows4 (a knob arm — the guide records that rung among the losers; the default never picks it), else rows2, and one-row forwards bypass it entirely ('one at a time for one row'; the harness additionally proves 'each row alone through the one-row kernel == its rows in the 8-row window'). A second knob rides the SAME law — 'geometry' (rows a simdgroup x simdgroups a threadgroup), 'each row's arithmetic is unchanged', bit-identical by construction. SERVED EVIDENCE (M5 Ultra, cache off, alternated twice against the previous kernel): 'one stream 503 to 513 tok/s on code and 348 to 351 on prose, 8 streams 947 to 985 and 713 to 731 in all, 32 streams 792 to 802 and 752 to 761, every reply equal to its solo and plain run'; cross-machine: '10-15% faster at 64 and 128 rows on an M3 Ultra, and 64 sessions reach 409 tok/s with #518'. THE DEMAND-SIDE HALF (companion commit #518 — one rule with the ladder): wide rungs only pay when ROUNDS are wide, and #518 widened them — 'The native server's shared round held at most 32 rows, so past 32 sessions it stopped scaling'; 'batch_rows now follows --parallel: four rows a lane, 64 at least (what the engine always allocated for a lone stream's lanes) and 128 at most'; the widening is memory-priced: 'Each row past 64 costs a Mamba state slot, 47 MiB'; served: '64 sessions 779-795 -> 968-1,033 tok/s on code and 740-753 -> 847-849 on chat'. ⛔ GRADER DRIFT CORRECTED (TIP-WINS): 'four rows a lane' in #518 is the SHARED-ROUND width (batch_rows — the workload, demand side), NOT a member-rows rung; the mb rungs 2/3/4 are #502's supply-side axis. The two ladders compose: #518 creates the wide members-per-expert population, #502's rung harvests it. THE PROOF SHAPE (load-bearing beyond this kernel): the harness compiles every candidate pass shape and bit-checks EACH against the engine's kernels at widths 1 through 128 ('Nemotron's routed experts at window widths: member-row pass shapes bit-checked against the engine's kernels, then timed'), printing '==' or 'DIFFER' per shape per width and exiting 1 on any differ ('every kernel: bits == the engine's, rows exact') — bit-identity asserted at EVERY width and EVERY rung, never sampled, and the same harness TIMES the shapes so the width decision stays measured. REGIME: MoE routed-expert mat-vecs where the unique-expert weight stream dominates and an expert's routed member count grows with batch width; any kernel with a members/rows-a-pass template axis; composes with a serving-side round-width widening that grows that count. ANTI-REGIME: one-row decode forwards (the ladder bypasses itself); ALU-bound loops (the prepared-activations negative says remaking per member is free); experts too few to fill the rung (near the null point take the incumbent); widths past the ceiling (six or eight members, or four at two simdgroups — lose 5-40%). KINSHIP (do not double-count): simdgroup-row-packing-reduction-amortization (gpu_09) owns reduction LANE-partitioning for row-packed dots; THIS owns the member-ROWS-per-pass width rungs with bit-identity at every rung and a measured null point. fewrow-tensor-tile-decode-into-rhs-operand (B198, with the B214 #225 per-dispatch-path row-tile axis rider) owns DECODING few-row tensor tiles into a rhs operand, validated per (type, dispatch-path); THIS validates by WIDTH at one path with bit equality as the gate. The B213 #30087 rider (GDN four-columns-per-warp, gpu_09 family) owns warp SEGMENT columns on a recurrent scan. row-parallelism-ladder-split-vs-pack (B110) splits ONE wide row across warps when rows are few — the single-row axis this rule never touches. m-group-shared-weight-scan-register-relief (B110) SPLITS the output-M axis at the register cliff while groups share one weight K-slice walk; THIS packs rows WIDER after reordering so the live set shrinks — opposite directions on the same physics (the register budget decides the rung). independent-accumulator-chains-hide-load-latency-at-capped-occupancy (B108) hides load latency with independent chains and is explicitly NOT bit-identical (tree reassociation, tolerance band); THIS is the order-preserving cousin — the reassociation never happens, so bit equality stays cheap and exact. moe-routed-down-sum-single-accumulate-pass (B98) fuses ONE row's k-expert fan-out + combine into a single accumulate pass; THIS widens the pass across an expert's MEMBERS. moe-per-expert-mixed-dispatch-worst-case-workspace (B186, category H) admits per expert by routed count inside one op; THIS chooses the pass width per round — both MoE dispatch-shape decisions, different axes. CITE: ashhart/TensorFold @ f1aef9c3f2ab85b2a68f2eed817e45eecbd04781 (origin/main 2026-10-10, Apache-2.0); commits 2985ed7e2bf7b969af6a14b1c7e6ffb2491ca7a8 (#502 — zig/kernels/metal/nemotron_experts.metal (the tf_experts_w kernel + the order-law comments), zig/src/families/nemotron/layers.zig expertRows ladder + the many/geo dispatch, zig/src/families/nemotron/backend.zig members default 3) + 6cb537422ca1890610fc77e75bb56ba176d96535 (#518 — batch_rows to 128, state.max_rows, the startup timing sweep); zig/tests/nemotron_experts.zig (the bit-check + timing harness, widths 1-128); docs/recipes/nemotron-3.5.md (the full measured ladder); docs/recipes/adding-a-zig-family.md (the Don't-bullet negatives + the 5-40% ceiling, the 4.4/2.3 ms cost model, the any-width bits law); CHANGELOG.md (#502/#518 entries, the M3 Ultra numbers); ZIG-PREVIEW.md item 4 (the bandwidth regime + the summation-order allowance). Batch 215 / Plan 215 (Research 251 N3).".to_string(),
            ref_shape: "// naive: the routed-expert member pass at a CONSTANT width — two member\n// rows a pass, chunks inner, so all 16 activations of the chunk are live\n// PER MEMBER (MB x 16 activation floats); two simdgroups. The width is\n// hard-wired: no ladder, no null point, one shape for a 2-row window and\n// a 64-row shared round alike. Wider rungs were simply unavailable — at\n// three members the live set is 48 floats and the register budget is\n// gone. (Bit-correct, just slow at width: the incumbent's unpack IS\n// shared per pass; what the constant width costs is the amortization —\n// the weight word serves one row per unpack no matter how few rows the\n// pass carries.)\n\nconst K_GROUP: usize = 16; // one 16-activation weight-word group\n\nfn qdot16_naive(w: &[u16; 4], xt: &[f32; 16], scale: f32, bias: f32, sum: f32) -> f32 {\n    // the one-row kernel's order: words i ascending, nibbles ascending\n    let mut accum = 0.0f32;\n    for i in 0..4 {\n        accum += xt[4 * i] * (w[i] & 0x000f) as f32\n            + xt[4 * i + 1] * (w[i] & 0x00f0) as f32\n            + xt[4 * i + 2] * (w[i] & 0x0f00) as f32\n            + xt[4 * i + 3] * (w[i] & 0xf000) as f32;\n    }\n    scale * accum + sum * bias\n}\n\n/// One weight-word group of one (expert, output row) over that expert's\n/// routed member rows, CONSTANT two a pass, pairs then a singles tail.\n/// out must hold members.len() results.\nfn group_pass_constant_two(\n    words: &[u16; 4],\n    acts: &[f32], // member activations, member * K_GROUP\n    members: &[usize],\n    scale: f32,\n    bias: f32,\n    out: &mut [f32],\n) {\n    let mut m = 0;\n    while m + 2 <= members.len() {\n        let mut xt = [[0.0f32; 16]; 2]; // 32 live activations a pass\n        let mut sums = [0.0f32; 2];\n        for b in 0..2 {\n            let base = members[m + b] * K_GROUP;\n            for (i, v) in acts[base..base + K_GROUP].iter().enumerate() {\n                xt[b][i] = *v;\n                sums[b] += *v;\n            }\n        }\n        for b in 0..2 {\n            out[m + b] = qdot16_naive(words, &xt[b], scale, bias, sums[b]);\n        }\n        m += 2;\n    }\n    // singles tail: the pass width cannot adapt, the tail just shrinks\n    for (b, &mem) in members[m..].iter().enumerate() {\n        let base = mem * K_GROUP;\n        let mut xt = [0.0f32; 16];\n        let mut sum = 0.0f32;\n        for (i, v) in acts[base..base + K_GROUP].iter().enumerate() {\n            xt[i] = *v;\n            sum += *v;\n        }\n        out[m + b] = qdot16_naive(words, &xt, scale, bias, sum);\n    }\n}\n\n/// Reachability entry so the naive shape is one call away.\npub fn naive_entry(words: &[u16; 4], acts: &[f32], members: &[usize], out: &mut [f32]) {\n    group_pass_constant_two(words, acts, members, 0.01, -0.1, out)\n}".to_string(),
            opt_pattern: "// repaired: the WIDTH LADDER. (1) The words-outer reorder — a\n// 16-group's four weight words become the OUTER loop, so only four\n// activations a member are live and three members fit a pass at four\n// simdgroups. (2) Every rung keeps each lane's summation order and the\n// same final reduce, so every width gives the one-row kernel's bits —\n// asserted below as BIT EQUALITY, never a tolerance. (3) The dispatch\n// is the source's expertRows ladder; the default is the measured\n// winner (3).\n\n/// The source's expertRows ladder: 3 -> the words-outer kernel at four\n/// simdgroups; >= 4 -> rows4 (a knob arm — the guide records that rung\n/// among the measured losers; the default never picks it); else rows2.\n/// One-row forwards bypass the ladder entirely ('one at a time').\nfn expert_rows_kernel(mb: usize) -> &'static str {\n    if mb == 3 {\n        \"tf_xup_w3\" // the measured winner — the promoted default\n    } else if mb >= 4 {\n        \"tf_xup_rows4\"\n    } else {\n        \"tf_xup_rows2\"\n    }\n}\n\n/// Pass economics the ladder trades on: full MB-rows passes plus a\n/// singles tail. An expert holding FEWER members than MB runs only\n/// singles — the null point ('equal at 2': a 3-wide rung never engages\n/// there); at 32 members it engages 10 times.\nfn pass_plan(members: usize, mb: usize) -> (usize, usize) {\n    (members / mb, members % mb)\n}\n\n/// The measured loser set (kept the bits, lost 5-40% — never ship):\n/// six or eight members a pass, or four at two simdgroups. The winning\n/// window is two to four members at four simdgroups.\nfn measured_loser(mb: usize, simdgroups: usize) -> bool {\n    mb >= 6 || (mb == 4 && simdgroups == 2)\n}\n\n/// The one-row kernel's word term: nibbles ascending, added into the\n/// running accumulator in word order — the order the packed form must\n/// reproduce per member ('each lane sums in tf_qdot16's order').\nfn word_term(word: u16, xt: &[f32; 4], acc: &mut f32) {\n    let q = [\n        (word & 0x000f) as f32,\n        (word & 0x00f0) as f32,\n        (word & 0x0f00) as f32,\n        (word & 0xf000) as f32,\n    ];\n    *acc += xt[0] * q[0] + xt[1] * q[1] + xt[2] * q[2] + xt[3] * q[3];\n}\n\n/// The words-outer pass over ONE weight-word group for MB members: the\n/// word unpacks once for all MB rows; each member's adds happen in the\n/// one-row kernel's order (words i ascending, nibbles ascending), so\n/// the results are bit-identical to the one-at-a-time form. order_log\n/// witnesses the per-member word-visit order.\nfn group_pass_packed<const MB: usize>(\n    words: &[u16; 4],\n    xt: &[[f32; 4]; MB],\n    sums: &[f32; MB],\n    scale: f32,\n    bias: f32,\n    order_log: &mut [Vec<u8>; MB],\n) -> [f32; MB] {\n    let mut acc = [0.0f32; MB];\n    for i in 0..4 {\n        let q = [\n            (words[i] & 0x000f) as f32,\n            (words[i] & 0x00f0) as f32,\n            (words[i] & 0x0f00) as f32,\n            (words[i] & 0xf000) as f32,\n        ];\n        for b in 0..MB {\n            acc[b] += xt[b][0] * q[0] + xt[b][1] * q[1] + xt[b][2] * q[2] + xt[b][3] * q[3];\n            order_log[b].push(i as u8);\n        }\n    }\n    for b in 0..MB {\n        acc[b] = scale * acc[b] + sums[b] * bias;\n    }\n    acc\n}\n\nfn rung<const MB: usize>(words: &[u16; 4], scale: f32, bias: f32, rnd: &mut impl FnMut() -> u32) {\n    let mut xt = [[0.0f32; 4]; MB];\n    let mut sums = [0.0f32; MB];\n    for b in 0..MB {\n        for v in xt[b].iter_mut() {\n            *v = (rnd() % 17) as f32 * 0.0625;\n        }\n        sums[b] = (rnd() % 33) as f32 * 0.03125;\n    }\n\n    // one at a time: each member walks words i ascending — the one-row\n    // kernel's order and the one-row accumulator sequence.\n    let mut one_acc = [0.0f32; MB];\n    let mut one_log: [Vec<u8>; MB] = std::array::from_fn(|_| Vec::new());\n    for b in 0..MB {\n        for i in 0..4 {\n            word_term(words[i], &xt[b], &mut one_acc[b]);\n            one_log[b].push(i as u8);\n        }\n    }\n\n    // packed: words outer, MB members a pass — the word unpacked once\n    // for all rows, the per-member add order unchanged.\n    let mut packed_log: [Vec<u8>; MB] = std::array::from_fn(|_| Vec::new());\n    let packed = group_pass_packed::<MB>(words, &xt, &sums, scale, bias, &mut packed_log);\n\n    for b in 0..MB {\n        let one = scale * one_acc[b] + sums[b] * bias;\n        // bit-identical: same summation order, so == is the gate — a\n        // tolerance band here would mean the rung reordered the reduce.\n        assert_eq!(\n            packed[b].to_bits(),\n            one.to_bits(),\n            \"MB={} row {} moved bits\",\n            MB,\n            b\n        );\n        assert_eq!(\n            packed_log[b], one_log[b],\n            \"MB={} row {} changed the order\",\n            MB, b\n        );\n    }\n}\n\n#[test]\nfn every_rung_gives_the_one_row_bits() {\n    let mut s: u32 = 0x2026_1007;\n    let mut rnd = move || {\n        s = s.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);\n        s\n    };\n    let words: [u16; 4] = [rnd() as u16, rnd() as u16, rnd() as u16, rnd() as u16];\n    let scale = 0.5 + (rnd() % 1000) as f32 / 1000.0;\n    let bias = -((rnd() % 100) as f32) / 500.0;\n    rung::<2>(&words, scale, bias, &mut rnd);\n    rung::<3>(&words, scale, bias, &mut rnd);\n    rung::<4>(&words, scale, bias, &mut rnd);\n}\n\n#[test]\nfn the_ladder_dispatch_and_its_null_point() {\n    // the dispatch table (the source's expertRows):\n    assert_eq!(expert_rows_kernel(2), \"tf_xup_rows2\");\n    assert_eq!(expert_rows_kernel(3), \"tf_xup_w3\");\n    assert_eq!(expert_rows_kernel(4), \"tf_xup_rows4\");\n    assert_eq!(expert_rows_kernel(8), \"tf_xup_rows4\"); // >= 4 clamps to rows4\n\n    // the null point: an expert holding 2 members never fills a 3-wide\n    // pass — the rung cannot engage, and the measurement reads 'equal\n    // at 2'. At 32 members it engages 10 times; the measured gain grows\n    // with width (2.35 -> 2.27 ms at 4 rows, 6.68 -> 6.48 at 16,\n    // 11.93 -> 11.24 at 32, 22.57 -> 20.58 at 64).\n    assert_eq!(pass_plan(2, 3), (0, 2));\n    assert_eq!(pass_plan(32, 3), (10, 2));\n    assert_eq!(pass_plan(64, 3), (21, 1));\n    assert_eq!(pass_plan(1, 3), (0, 1)); // one row: one at a time\n\n    // the measured loser set: six or eight members, or four at two\n    // simdgroups, lose 5-40%; the window two to four at four wins.\n    assert!(measured_loser(6, 4));\n    assert!(measured_loser(8, 4));\n    assert!(measured_loser(4, 2));\n    assert!(!measured_loser(2, 4));\n    assert!(!measured_loser(3, 4));\n    assert!(!measured_loser(4, 4));\n}".to_string(),
        },
    ]
}
